def add_nio(self, request):
        """
        Adds an NIO (Network Input/Output) for an IOU instance.

        Mandatory request parameters:
        - id (IOU instance identifier)
        - slot (slot number)
        - port (port number)
        - port_id (unique port identifier)
        - nio (nio type, one of the following)
            - "NIO_UDP"
                - lport (local port)
                - rhost (remote host)
                - rport (remote port)
            - "NIO_GenericEthernet"
                - ethernet_device (Ethernet device name e.g. eth0)
            - "NIO_TAP"
                - tap_device (TAP device name e.g. tap0)

        Response parameters:
        - same as original request

        :param request: JSON request
        """

        if request == None:
            self.send_param_error()
            return

        # JSON schema validation for the request
        schema = {
            "type": "object",
            "properties": {
                "id": {"type": "string"},
                "slot": {"type": "integer"},
                "port": {"type": "integer"},
                "port_id": {"type": "string"},
                "nio": {"type": "string", "enum": ["NIO_UDP", "NIO_GenericEthernet", "NIO_TAP"]},
                "lport": {"type": "integer"},
                "rhost": {"type": "string"},
                "rport": {"type": "integer"},
                "tap_device": {"type": "string"},
                "ethernet_device": {"type": "string"}
            },
            "required": ["id", "slot", "port", "port_id", "nio"],
            "if": {
                "properties": {"nio": {"const": "NIO_UDP"}}
            },
            "then": {
                "required": ["lport", "rhost", "rport"]
            },
            "else": {
                "if": {
                    "properties": {"nio": {"const": "NIO_TAP"}}
                },
                "then": {
                    "required": ["tap_device"]
                },
                "else": {
                    "if": {
                        "properties": {"nio": {"const": "NIO_GenericEthernet"}}
                    },
                    "then": {
                        "required": ["ethernet_device"]
                    }
                }
            }
        }

        validate(request, schema)

        log.debug("received request {}".format(request))
        iou_id = request["id"]
        if iou_id not in self._iou_instances:
            self.send_custom_error("IOU device id {} doesn't exist".format(iou_id))
            return
        iou_instance = self._iou_instances[iou_id]

        slot = request["slot"]
        port = request["port"]

        try:
            nio = None
            if request["nio"] == "NIO_UDP":
                lport = request["lport"]
                rhost = request["rhost"]
                rport = request["rport"]
                nio = NIO_UDP(lport, rhost, rport)
            elif request["nio"] == "NIO_TAP":
                tap_device = request["tap_device"]
                nio = NIO_TAP(tap_device)
            elif request["nio"] == "NIO_GenericEthernet":
                ethernet_device = request["ethernet_device"]
                nio = NIO_GenericEthernet(ethernet_device)
            if not nio:
                raise IOUError("Requested NIO doesn't exist or is not supported: {}".format(request["nio"]))
        except IOUError as e:
            self.send_custom_error(str(e))
            return

        try:
            iou_instance.slot_add_nio_binding(slot, port, nio)
        except IOUError as e:
            self.send_custom_error(str(e))
            return

        # for now send back the original request
        self.send_response(request)
